import logo from './logo.svg';
import './App.css';
import {useState} from "react";

function App() {
    const [user, setUser] = useState('unknown');
    const handleClick = ()=>{
        fetch('/api-test')
            .then(res=> res.json())
            .then(data => alert(JSON.stringify(data)));
    }

    return (
        <div className="App">
            <h1>MAIN</h1>
            <h3>user : {user}</h3>

            <div style={{display:'flex'}}>
                <div>
                    <h3>Sign up</h3>
                </div>
                <div>

                </div>
            </div>

            {/*Your Name : &nbsp;
            <input type="text"  onChange={(e)=>{setUser(e.target.value)}}/>*/}
            <br/>
            <button onClick={handleClick}>api test
            </button>
        </div>
    );
}

export default App;
